<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api, currentUser, messageOf } from './services.js'
import { conversationProfile as profile, loadConversationProfile, chooseConversationProfile, updateAdminSignature } from './conversation-profile.js'
const props = defineProps({ pickerOnly: Boolean })
const emit = defineEmits(['selected'])
const $q = useQuasar(), dialog = ref(false), busy = ref(false), editing = ref(false)
const form = reactive({ nick: '', signatureEnabled: true })
const label = computed(() => profile.current?.signatureEnabled === false ? 'Sem assinatura' : (profile.current?.nick || currentUser.value?.nick || 'AitoSoftwares Admin') + ':')
async function open() {
  try { await loadConversationProfile(); if (!profile.canChoose && props.pickerOnly) { emit('selected', profile.current); return } dialog.value = true }
  catch (error) { $q.notify({ type: 'negative', message: messageOf(error) }) }
}
async function select(id) { busy.value = true; try { const current = await chooseConversationProfile(id); dialog.value = false; emit('selected', current) } catch (error) { $q.notify({ type: 'negative', message: messageOf(error) }) } finally { busy.value = false } }
function edit() { const own = profile.canChoose ? profile.profiles.find(item=>item.role==='admin') : profile.current; Object.assign(form, { nick: own?.nick || 'AitoSoftwares Admin', signatureEnabled: own?.signatureEnabled !== false }); editing.value = true }
async function save() { busy.value = true; try { if (profile.canChoose) await updateAdminSignature(form); else { currentUser.value = (await api.patch('/auth/profile', form)).data.user; await loadConversationProfile() } editing.value = false; $q.notify({ type: 'positive', message: 'Assinatura de conversa atualizada.' }) } catch (error) { $q.notify({ type: 'negative', message: messageOf(error) }) } finally { busy.value = false } }
onMounted(() => { if (!props.pickerOnly) loadConversationProfile().catch(()=>{}) })
defineExpose({ open })
</script>
<template>
  <div v-if="!pickerOnly" class="conversation-signature"><q-icon name="draw"/><div><small>Assinatura de conversa</small><strong>{{ label }}</strong><span v-if="profile.current?.name && profile.current.name !== profile.current.nick">{{ profile.current.name }}</span></div><q-btn flat no-caps dense :label="profile.canChoose ? 'Trocar perfil' : 'Editar'" icon="manage_accounts" @click="open"/></div>
  <q-dialog v-model="dialog"><q-card class="conversation-profile-dialog"><q-card-section class="row items-center"><div class="col"><div class="text-h6">Assinatura de conversa</div><p class="text-caption text-grey-7 q-mb-none">{{ profile.canChoose ? 'Escolha quem assina suas respostas e a fila de Meus atendimentos.' : 'Suas respostas são identificadas com esta assinatura.' }}</p></div><q-btn flat round icon="close" v-close-popup/></q-card-section><q-separator/><q-list v-if="profile.canChoose" separator><q-item v-for="item in profile.profiles" :key="item.id" clickable :disable="busy" :active="profile.current?.id === item.id" @click="select(item.id)"><q-item-section avatar><q-avatar color="teal-1" text-color="teal-9" :icon="item.role === 'admin' ? 'admin_panel_settings' : 'person'"/></q-item-section><q-item-section><q-item-label>{{ item.name }}</q-item-label><q-item-label caption>{{ item.signatureEnabled ? '*' + item.nick + ':*' : 'Sem assinatura' }}</q-item-label></q-item-section><q-item-section side><q-badge :color="item.role === 'admin' ? 'teal-8' : 'blue-grey-6'">{{ item.role === 'admin' ? 'Administrador' : 'Colaborador' }}</q-badge><q-icon v-if="profile.current?.id === item.id" name="check" class="q-mt-xs"/></q-item-section></q-item></q-list><q-card-section v-else><strong>{{ label }}</strong></q-card-section><q-card-actions align="right"><q-btn flat no-caps color="primary" :label="profile.canChoose ? 'Editar minha assinatura de admin' : 'Editar minha assinatura'" @click="edit"/></q-card-actions><q-card-section v-if="editing"><q-form @submit="save"><q-input v-model="form.nick" outlined maxlength="60" label="Nome da assinatura" hint="O negrito é aplicado automaticamente. Não precisa digitar asteriscos." :rules="[value=>Boolean(value.trim()) || 'Informe a assinatura']"/><q-toggle v-model="form.signatureEnabled" label="Assinar as respostas"/><div class="signature-example"><b>{{ form.nick.replace(/[\r\n*_`]/g, '').replace(/:+$/, '') }}:</b><br/>Olá! Vou continuar seu atendimento.</div><q-btn type="submit" no-caps color="primary" label="Salvar assinatura" :loading="busy"/></q-form></q-card-section></q-card></q-dialog>
</template>
<style scoped>.conversation-signature{display:flex;align-items:center;gap:9px;flex:none;padding:8px 12px;background:#effaf6;border-bottom:1px solid #d6e9e1;color:#235e4f;min-width:0}.conversation-signature>div{min-width:0;flex:1}.conversation-signature small{font-size:9px;display:block;color:#6a8177}.conversation-signature strong{font-size:12px;display:inline-block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.conversation-signature span{font-size:10px;margin-left:8px;color:#6a8177}.conversation-profile-dialog{width:500px;max-width:94vw;max-height:88dvh;border-radius:20px}.signature-example{padding:12px;margin:12px 0;border-radius:10px;background:#e6f8df;line-height:1.7;font-size:13px}.conversation-signature .q-btn{font-size:11px}@media(max-width:500px){.conversation-signature{padding:7px 9px}.conversation-signature span{display:none}.conversation-signature .q-btn{font-size:10px}.conversation-signature strong{max-width:200px}}</style>
